import pandas as pd,numpy as np,glob
from scipy.optimize import least_squares
F={f:pd.read_csv(f).iloc[::10].reset_index(drop=True) for f in glob.glob('train/*.csv')}
def simQ(p,d,dt=0.01):
  a,b,c,e,kp,ki,Tq=p
  V=d.voltage_pu.values;Vs=d.voltage_setpoint_pu.values;th=d.bus_angle_rad.values
  n=len(V);Q=np.empty(n);Q0=d.reactive_power_pu[0];V0=V[0];qo=Q0;dl=th[0];xi=0
  for i in range(n):
    Q[i]=qo;er=th[i]-dl;w=kp*er+xi
    qc=Q0+a*(Vs[i]-V0)+b*(V[i]-V0)+c*er+e*w
    dl+=dt*w;xi+=dt*ki*er;qo+=dt/Tq*(qc-qo)
  return Q
def res(p,ret=False):
  r=[]
  for f,d in F.items():
    Q=simQ(p,d);r.append(Q-d.reactive_power_pu)
    if ret: print(f,np.std(r[-1]))
  return np.concatenate(r)
best=None
for x0 in [[0.2,2,0,-20*0.00265,1,0.1,0.05],[0.6,0.6,1,0,5,1,0.05]]:
  s=least_squares(res,x0,bounds=([-20,-20,-20,-20,0,0,0.006],[20,20,20,20,50,50,2]));print(s.x,s.cost)
  if best is None or s.cost<best.cost:best=s
res(best.x,True);np.save('qpll.npy',best.x)
